//! Per-clip grade DAG. Evaluation-local node cache: no stale cross-frame pixels.
use std::collections::{BTreeMap,BTreeSet};use std::sync::Arc;use serde::{Serialize,Deserialize};use crate::{effects::Frame,keyframe::Prop,masks::{MaskLayer,Ctx},model::Effect};
pub const INPUT:&str="input";
pub const GRADES:&[&str]=&["lut","blur","sharpen","exposure","contrast","saturation","temperature","tint","color_wheels","curves","levels","brightness_contrast","channel_mixer","colorize","invert","sepia","hsl","rgb_curves","hue_curves","film_print","print_stock","bleach_bypass","white_balance","color_transfer","tonemap","highlight_rolloff","split_toning","color_space","primaries","log_wheels","linear_grade","luminance_shoulder","color_managed","point_curves","cdl","asc_cdl","acescct_primaries","film_soft_shoulder","film_luma_grain","white_adaptation","soft_gamut_ray","color_boost","midtone_detail","dehaze","skin_smooth","hdr_zones","look"];
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct Node{pub id:String,pub kind:String,#[serde(default)]pub inputs:Vec<String>,#[serde(default)]pub effect:Option<Effect>,#[serde(default)]pub weights:Vec<Prop>,#[serde(default)]pub mask:Option<MaskLayer>,#[serde(default)]pub bypass:bool}
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct Graph{pub nodes:BTreeMap<String,Node>,pub output:String,#[serde(default="budget")]pub cache_budget_mb:usize}
fn budget()->usize{256}impl Default for Graph{fn default()->Self{Self{nodes:BTreeMap::new(),output:INPUT.into(),cache_budget_mb:budget()}}}
#[derive(Default,Debug,Serialize)]pub struct Stats{pub evaluated_nodes:usize,pub cache_hits:usize,pub peak_cached_bytes:usize,pub unreachable_nodes:usize}
fn finite(p:&Prop)->bool{serde_json::to_value(p).ok().and_then(|v|crate::guard::sanitize(&v,crate::guard::limits(),0).ok()).is_some()&&p.base.is_finite()&&p.keys.windows(2).all(|k|k[0].t<k[1].t)&&p.keys.iter().all(|k|k.t.is_finite()&&k.v.is_finite()&&k.bez.map(|b|b.iter().all(|v|v.is_finite())).unwrap_or(true))}
impl Graph{
 pub fn validate(&self,complete:bool)->Result<Vec<String>,String>{
 crate::guard::sanitize(&serde_json::to_value(self).map_err(|e|e.to_string())?,crate::guard::limits(),0)?;
 if self.nodes.len()>64||!(1..=1024).contains(&self.cache_budget_mb){return Err("grade graph max64 nodes; cache budget1..1024MiB".into())}if self.output!=INPUT&&!self.nodes.contains_key(&self.output){return Err("missing graph output".into())}
 for(id,n)in &self.nodes{if id==INPUT||id!=&n.id||id.is_empty()||id.len()>128{return Err("invalid grade node identity".into())}if !["grade","parallel","layer"].contains(&n.kind.as_str()){return Err("node kind grade/parallel/layer".into())}if n.inputs.len()>16||n.inputs.iter().collect::<BTreeSet<_>>().len()!=n.inputs.len(){return Err("max16 unique ordered node inputs".into())}if n.kind=="grade"{if n.inputs.len()>1||complete&&n.inputs.len()!=1{return Err(format!("grade node {id} requires one input"))}let e=n.effect.as_ref().ok_or("grade requires effect")?;if !GRADES.contains(&e.kind.as_str())||e.strings.contains_key("mask_layer"){return Err("unsupported/non-color grade effect or implicit clip mask binding".into())}if !e.params.values().all(finite){return Err("nonfinite node property".into())}}else if n.effect.is_some()||complete&&n.inputs.len()<2{return Err(format!("mixer node {id} requires2..16inputs and no effect"))}
 if n.weights.len()!=n.inputs.len()||!n.weights.iter().all(finite){return Err("one finite weight property per input".into())}for src in &n.inputs{if src!=INPUT&&!self.nodes.contains_key(src){return Err("connection source does not exist".into())}}
 if let Some(m)=&n.mask{if !m.strings.is_empty()||!m.path_keys.windows(2).all(|k|k[0].t<k[1].t)||!["rect","ellipse","path","linear","radial","luma","color","hsl","alpha","noise"].contains(&m.kind.as_str())||!m.props.values().all(finite)||!m.path_keys.iter().all(|k|k.t.is_finite()&&k.points.iter().all(|p|[p.x,p.y,p.ix,p.iy,p.ox,p.oy,p.f].iter().all(|v|v.is_finite())))||!m.points.iter().all(|p|[p.x,p.y,p.ix,p.iy,p.ox,p.oy,p.f].iter().all(|v|v.is_finite())){return Err("unsupported or nonfinite node mask; no external matte references".into())}}
 }
 fn visit(id:&str,g:&Graph,active:&mut BTreeSet<String>,done:&mut BTreeSet<String>,order:&mut Vec<String>)->Result<(),String>{if id==INPUT||done.contains(id){return Ok(())}if !active.insert(id.into()){return Err("grade graph cycle".into())}for src in &g.nodes[id].inputs{visit(src,g,active,done,order)?}active.remove(id);done.insert(id.into());order.push(id.into());Ok(())}
 let mut order=Vec::new();let(mut active,mut done)=(BTreeSet::new(),BTreeSet::new());visit(&self.output,self,&mut active,&mut done,&mut order)?;
 // Cycles in parked nodes are invalid too, but don't evaluate parked nodes.
 let reachable=order.clone();for id in self.nodes.keys(){visit(id,self,&mut active,&mut done,&mut order)?}Ok(reachable)
 }
 pub fn validate_project(&self,p:&crate::model::Project)->Result<(),String>{self.validate(false)?;for n in self.nodes.values(){if let Some(e)=&n.effect{let q=&p.color_pipeline;if let Some(w)=e.strings.get("bound_linear_gamut"){let g=w.parse::<usize>().map_err(|_|"bad node bound linear gamut")?;if !q.enabled||g!=q.working_gamut||e.params.get("gamut").map(|v|(v.base,v.keys.is_empty(),v.expr.is_empty()))!=Some((g as f64,true,true)){return Err("node managed linear effect no longer matches project working gamut".into())}}if let Some(w)=e.strings.get("wrapper_working_gamut"){if !q.enabled||w.parse::<usize>().ok()!=Some(q.working_gamut){return Err("node wrapper working gamut changed".into())}}if let Some(w)=e.strings.get("wrapper_reference_white"){if w.parse::<f64>().ok()!=Some(q.reference_white){return Err("node wrapper reference white changed".into())}}}}Ok(())}
 pub fn apply(&self,f:&mut Frame,t:f64,seed:u64,fps:f64)->Result<Stats,String>{
 super::frame::validate(f)?;let order=self.validate(false)?;if !t.is_finite()||!fps.is_finite()||fps<=0.{return Err("finite node time and positive fps required".into())}if self.output==INPUT{return Ok(Stats{unreachable_nodes:self.nodes.len(),..Default::default()})}
 // Complete connectivity is needed only for reachable nodes, so parked edits are harmless.
 for id in &order{let n=&self.nodes[id];if n.kind=="grade"&&n.inputs.len()!=1||n.kind!="grade"&&n.inputs.len()<2{return Err(format!("incomplete reachable node {id}"))}}
 let bytes=f.d.len().checked_mul(4).ok_or("grade frame byte overflow")?;let cap=self.cache_budget_mb*1024*1024;if bytes>cap{return Err("grade frame exceeds node cache budget".into())}
 let mut uses:BTreeMap<String,usize>=BTreeMap::new();for id in &order{for src in &self.nodes[id].inputs{*uses.entry(src.clone()).or_default()+=1;}}*uses.entry(self.output.clone()).or_default()+=1;
 let mut cache:BTreeMap<String,Arc<Frame>>=BTreeMap::new();crate::guard::reserve(bytes);cache.insert(INPUT.into(),Arc::new(Frame{w:f.w,h:f.h,d:f.d.clone()}));let mut stats=Stats{unreachable_nodes:self.nodes.len()-order.len(),..Default::default()};let mut read=BTreeSet::new();
 for id in order{crate::guard::check();let n=&self.nodes[&id];let ins:Vec<_>=n.inputs.iter().map(|src|{if !read.insert(src.clone()){stats.cache_hits+=1;}cache.get(src).cloned().ok_or("missing cached dependency")}).collect::<Result<_,_>>()?;
 let projected=(cache.len()+1).checked_mul(bytes).ok_or("node cache overflow")?;if projected>cap{return Err("grade DAG live node cache exceeds budget; raise cache_budget_mb or reduce branches/canvas".into())}crate::guard::reserve(bytes);stats.peak_cached_bytes=stats.peak_cached_bytes.max(projected);
 let mut out=Frame{w:f.w,h:f.h,d:ins[0].d.clone()};
 if !n.bypass{if n.kind=="grade"{let e=n.effect.as_ref().unwrap();if ["blur","sharpen"].contains(&e.kind.as_str()){let r=e.params.get("radius").map(|v|v.at(t)).unwrap_or(if e.kind=="blur"{4.}else{2.});let amount=e.params.get("amount").map(|v|v.at(t)).unwrap_or(0.8);if !r.is_finite()||!(0. ..=512.).contains(&r)||!amount.is_finite()||!(0. ..=3.).contains(&amount){return Err("node spatial radius0..512/amount0..3 required".into())}}crate::effects::apply(&e.kind,&e.params,&e.strings,&mut out,t,seed)?;}else{
 let weights=n.weights.iter().map(|p|p.at(t)).collect::<Vec<_>>();if weights.iter().any(|v|!v.is_finite()||*v<0.||*v>1.){return Err("mixer weight must be0..1 at evaluated time".into())}
 if n.kind=="parallel"{let sum:f64=weights.iter().sum();if sum<=0.{return Err("parallel mixer positive total weight required".into())}for(i,px)in out.d.chunks_exact_mut(4).enumerate(){if i%65536==0{crate::guard::check()}for j in 0..3{px[j]=(ins.iter().zip(&weights).map(|(a,w)|a.d[i*4+j] as f64*w).sum::<f64>()/sum) as f32;}}}
 else{for (a,w)in ins.iter().zip(&weights).skip(1){for(i,px)in out.d.chunks_exact_mut(4).enumerate(){if i%65536==0{crate::guard::check()}for j in 0..3{px[j]=(px[j] as f64*(1.-w)+a.d[i*4+j] as f64*w) as f32;}}}}
 }
 if let Some(mask)=&n.mask{let refs=|_:&str|None;let ctx=Ctx{refs:&refs,fps};let cov=crate::masks::layer_coverage(mask,&ins[0],t,&ctx);for(i,px)in out.d.chunks_exact_mut(4).enumerate(){if i%65536==0{crate::guard::check()}let a=cov[i];if !a.is_finite(){return Err("nonfinite node mask coverage".into())}for j in 0..3{px[j]=ins[0].d[i*4+j]*(1.-a)+px[j]*a;}}}
 }
 // Grading/mixers own RGB only, and retain the first input alpha exactly.
 for(i,px)in out.d.chunks_exact_mut(4).enumerate(){px[3]=ins[0].d[i*4+3];}super::frame::validate(&out)?;stats.evaluated_nodes+=1;cache.insert(id.clone(),Arc::new(out));drop(ins);
 for src in &n.inputs{let count=uses.get_mut(src).unwrap();*count-=1;if *count==0{cache.remove(src);}}
 if uses.get(&id).copied().unwrap_or(0)==0{cache.remove(&id);}
 }
 let out=cache.remove(&self.output).ok_or("missing graph result")?;*f=Arc::try_unwrap(out).unwrap_or_else(|a|Frame{w:a.w,h:a.h,d:a.d.clone()});Ok(stats)
 }
}
